#!/usr/bin/env python3
"""P58: analyze the private 86Box EMU8000 WAV generated by original Win95 MIDI.

No private/Creative audio, ROM, SF2 or windows image leaves the ephemeral CI
runner. JSON reports only numbers: dominant note frequency, sample-exact rate,
spectral amplitudes at fundamental and harmonics for the original generated
sine probe vs a normal GM piano.
"""
from __future__ import annotations
import array
import math
import struct
import wave
from pathlib import Path


def goertzel(samples: list[float], rate: int, hz: float) -> float:
    # Arbitrary real-frequency DFT projection. Avoid required scipy/numpy.
    coeff = 2.0 * math.cos(2.0 * math.pi * hz / rate)
    v1 = v2 = 0.0
    for s in samples:
        v = s + coeff * v1 - v2
        v2, v1 = v1, v
    p = v1 * v1 + v2 * v2 - coeff * v1 * v2
    return max(0.0, p)


def analyze_wav(path: Path, note: int=48) -> dict:
    with wave.open(str(path), "rb") as f:
        rate = f.getframerate()
        chans = f.getnchannels()
        width = f.getsampwidth()
        frames = f.getnframes()
        if chans != 2 or width != 2 or rate < 22050 or frames < rate:
            raise ValueError("Unexpected 86Box WAV format/rate/length")
        f.setpos(int(rate*0.22))
        n = min(32768, frames - int(rate*0.22))
        raw = f.readframes(n)
    vals = array.array("h")
    vals.frombytes(raw)
    # Actions runners are little endian x64; explicit validate at runtime.
    if struct.pack("=H", 1) != b"\x01\x00":
        vals.byteswap()
    mono = [(vals[2*i]+vals[2*i+1])/(2*32768.0) for i in range(len(vals)//2)]
    mean = sum(mono)/len(mono)
    mono = [v-mean for v in mono]
    rms = math.sqrt(sum(v*v for v in mono)/len(mono))
    expected = 440.0 * 2.0**((note - 69)/12.0)
    # Window the excerpt to suppress transients and leakage, and inspect
    # frequencies around the expected note. No WAV is uploaded.
    n=len(mono)
    windowed = [v * (0.5-0.5*math.cos(2*math.pi*i/(n-1))) for i,v in enumerate(mono)]
    probes = [(expected-20+i*.5, 0) for i in range(81)]
    probes = [(f,goertzel(windowed,rate,f)) for f,_ in probes]
    dominant=max(probes,key=lambda z:z[1])
    harmonics = [goertzel(windowed,rate,expected*k) for k in range(1,7)]
    power_harm=sum(harmonics[1:])
    harmonic_delta_db = 10*math.log10((harmonics[0]+1e-30)/(power_harm+1e-30))
    return {
        "wavetable_rate_hz":rate,"source_frames":frames,
        "window_start_seconds":.22,"window_frames":len(mono),
        "window_rms_dbfs":round(20*math.log10(max(rms,1e-15)),2),
        "requested_midi_note":note,
        "expected_equal_tempered_hz":round(expected,3),
        "dominant_frequency_hz_in_expected_band":round(dominant[0],2),
        "dominant_deviation_hz":round(dominant[0]-expected,2),
        "fundamental_vs_harmonics_2_to_6_db":round(harmonic_delta_db,2),
        "harmonic_powers_1_to_6_relative":[round(v/max(harmonics[0],1e-30),6) for v in harmonics],
        "no_raw_wav_exported":True
    }
